const $=s=>document.querySelector(s),esc=x=>String(window.AndroidUI?AndroidUI.text(x):x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=localStorage.getItem('safelease-language')||'en',user=null,csrf='',lease=null,screening=null,view='home',stream=null,cameraKind='',cameraSupplement=false,leaseReceivedAt=0,cameraRequest=0;
let viewRevision=0;
const renderedContexts=new WeakMap(),referenceResults=new WeakMap();
let referenceRequest=0,referenceCatalog=null;
const referenceKinds={listings:['Listing leads','房源线索'],agents:['CEA registry snapshot','CEA登记快照'],rentals:['Historical whole-flat rents','历史整租租金'],guides:['Guides','指南'],community:['Community','社区']};
function beginView(next){view=next;return ++viewRevision;}
function currentView(ticket){return ticket===viewRevision;}
async function pageRead(path,ticket){try{return await api(path);}catch(e){if(!currentView(ticket)){e.staleNavigation=true;}throw e;}}
const tr=(en,zh)=>lang==='zh'?zh:en;
const codeText={lease_access_denied:['You do not have access to this lease.','你无权访问此租约。'],invalid_credentials:['Email or password is incorrect.','邮箱或密码不正确。'],login_required:['Please sign in again.','请重新登录。'],version_changed_refresh:['This record changed. Refresh and review the latest version.','记录已变化，请刷新后查看最新版本。'],confirmation_window_closed:['The server confirmation window has closed. Create a supplement.','服务端确认窗口已关闭，请创建补充版本。'],supplement_required:['A separate supplement is required.','需要创建独立补充版本。'],invite_identity_mismatch:['This invitation belongs to another account.','邀请不属于当前账户。'],invite_expired_or_used:['Invitation expired, revoked or already used.','邀请已过期、撤销或使用。'],activation_invalid:['The activation credential is invalid or expired.','激活凭证无效或已过期。'],rate_limited:['Too many requests. Wait one minute and try again.','请求过于频繁，请一分钟后重试。'],decision_already_recorded:['Your decision is already recorded on this version.','你已对该版本作出决定。'],password_12_to_256:['Use a password with 12–256 characters.','密码需要12至256个字符。']};
function notify(message,{persistent=false}={}){const box=$('#message');box.replaceChildren();const text=document.createElement('span');text.className='message-text';text.textContent=message;box.append(text);if(persistent){const dismiss=document.createElement('button');dismiss.type='button';dismiss.textContent=tr('Dismiss','关闭');dismiss.onclick=()=>box.style.display='none';box.append(dismiss);}box.style.display='flex';clearTimeout(notify.timer);if(!persistent)notify.timer=setTimeout(()=>box.style.display='none',7000);}
Object.assign(codeText,{invalid_text:['Please fill in the required text or reason.','请填写必要的文字或原因。'],empty_export_response:['The download response was empty. Retry and choose a location in the Android save dialog.','文件响应为空，请重试并在Android保存窗口中选择位置。'],export_hash_mismatch:['Download integrity check failed. No file was saved. Retry.','下载完整性校验失败，未保存文件，请重试。'],export_length_mismatch:['The file transfer was incomplete. Retry.','文件传输不完整，请重试。'],photo_invalid_or_over_20_megapixels:['This photo is damaged or exceeds 20 megapixels. Try a lower camera resolution.','照片损坏或超过2000万像素，请降低相机分辨率后重试。'],invalid_date:['Please enter a valid calendar date.','请输入有效日期。'],invalid_amount:['Please enter a valid amount.','请输入有效金额。'],export_busy_retry:['Another evidence file is being prepared. Try again shortly.','正在准备另一份证据文件，请稍后重试。']});
function error(e,form){if(e?.staleNavigation)return;const pair=codeText[e.message],message=pair?tr(...pair):tr('Could not complete this action. Please check your input and try again.','操作未完成，请核对输入后重试。');if(form?.isConnected){form.querySelector('.form-error')?.remove();const box=document.createElement('div');box.className='form-error';box.setAttribute('role','alert');box.tabIndex=-1;const text=document.createElement('p');text.textContent=message;const dismiss=document.createElement('button');dismiss.type='button';dismiss.textContent=tr('Dismiss','关闭');dismiss.onclick=()=>box.remove();box.append(text,dismiss);form.append(box);box.focus();}else notify(message,{persistent:true});}
Object.assign(codeText,{screening_access_denied:['This screening is private to its owner.','此房源预查仅限创建者访问。'],screening_already_linked:['This screening is linked and locked. Add new checks inside its lease.','此预查已关联并锁定，请在租约内添加新检查。'],screening_share_consent_required:['Confirm sharing the selected observations with lease members.','请确认向租约成员开放所选预查记录。'],invalid_note:['The note is too long or has an invalid format. Shorten it and retry; nothing was silently removed.','备注过长或格式无效，请缩短后重试；系统未静默删除内容。'],capture_request_conflict:['This capture identifier already has different content. Refresh and start a new capture.','此拍摄标识已有不同内容，请刷新后重新拍摄。'],invalid_photo_reference:['A referenced photo is invalid. Refresh the record and retry.','照片引用无效，请刷新记录后重试。'],decision_reason_required:['Please enter a reason for the dispute or refusal.','请填写异议或拒绝的原因。']});
async function api(path,b,extra={}){let r;try{r=await fetch('/api'+path,{method:b===undefined?'GET':'POST',credentials:'same-origin',headers:b===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf,...extra},body:b===undefined?undefined:JSON.stringify(b)});}catch{throw Error(tr('Network unavailable. No synchronization confirmed. Reconnect and refresh.','网络不可用，未确认同步成功。请恢复网络后刷新。'));}const out=await r.json();if(!r.ok)throw Error(out.error||'request_failed');return out;}
const field=(name,en,zh,type='text',value='',attrs='')=>`<label>${tr(en,zh)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const btn=(act,en,zh,attrs='')=>`<button type="button" data-act="${act}" ${attrs}>${tr(en,zh)}</button>`;
const note=(name,en,zh,value='')=>`<label>${tr(en,zh)}<textarea name="${name}" maxlength="4000">${esc(value)}</textarea></label>`;
const date=x=>x?new Date(x).toLocaleString(lang==='zh'?'zh-CN':'en-SG',{timeZone:'Asia/Singapore'}):tr('Not supplied','未提供');
const dollars=x=>'S$'+(x/100).toFixed(2);
const statusNames={pending:['Awaiting independent decisions','等待独立决定'],bilateral:['Both confirmed this version','双方已确认此版本'],disputed:['Disputed','存在异议'],refused:['Participation refused','已拒绝参与'],one_sided_timeout:['One-sided · window closed','单方记录 · 窗口已关闭']};
const badge=v=>`<span class="status ${esc(v.status)}">${tr(...(statusNames[v.status]||[v.status,v.status]))}</span>`;
function renderCheck(c){const r=JSON.parse(c.result),labels={not_checked:['Not checked','未检查'],failed:['Query failed','查询失败'],matches_need_review:['Matches found · review sources','找到匹配 · 请复核来源'],no_match_inconclusive:['No matches · inconclusive','未找到匹配 · 无法判断真伪'],user_reported_not_verified:['User-reported observation','用户自报观察']};const reasons={provider_not_configured:['Provider not configured','服务尚未配置'],insufficient_name_input:['Not enough usable name information; no identity check was performed','可用姓名信息不足，未核实身份'],insufficient_register_observation:['Registration number and observation are needed; no register result verified','需要登记号码及观察记录，未核验登记结果'],free_quota_exhausted:['Free lookup allowance exhausted; no paid purchase was made','免费额度已用完，未购买付费额度'],network_or_timeout:['Service unavailable or timed out','服务不可用或超时']};const comparisonLabels={match:['Visible characters match · needs review','可见字符一致 · 仍需复核'],stop:['Visible characters differ · stop and review','可见字符不一致 · 请停止并复核'],empty:['Names not supplied','未提供姓名'],invalid:['Unsupported name input','姓名格式不支持'],few:['Too few visible characters','可见字符不足'],company:['Company name needs separate review','公司名称需另行复核']};return `<div class="listrow result-card check-${c.status}" data-check-id="${esc(c.id)}" data-check-kind="${esc(c.kind)}" data-check-status="${esc(c.status)}"><h3>${esc(enumText(checkKinds,c.kind))} · ${tr(...(labels[c.status]||[c.status,c.status]))}</h3><p class="meta">${esc(c.source)}<br>${esc(c.object)}<br>${tr('Checked at','检查时间')}: ${date(c.created)} (SGT)</p>${r.reason?`<p>${tr(...(reasons[r.reason]||[r.reason,r.reason]))}</p>`:''}${r.comparison?`<p class="comparison-result ${r.comparison==='stop'?'comparison-stop':''}">${tr(...(comparisonLabels[r.comparison]||[r.comparison,r.comparison]))}</p>`:''}${r.note?`<p class="pre">${esc(r.note)}</p>`:''}${(r.matches||[]).map(m=>`<p>${m.link?`<a href="${esc(m.link)}" target="_blank" rel="noopener noreferrer">${esc(m.title)}</a>`:esc(m.title)}${m.match_kind?' · '+esc(m.match_kind):''}</p>`).join('')}<p class="muted">${c.kind==='paynow_helper'?tr('Only user-entered visible text was compared; no bank connection or identity, account ownership or property verification.','仅比较用户输入的可见文字；未连接银行，也未核实身份、账户归属或产权。'):c.kind==='cea_self_report'?tr('This is your observation, not a platform-verified register result or proof of the contact’s identity or ownership.','这是用户自报观察，不是平台核验的登记结果，也不证明联系人身份或产权。'):tr('A matching or missing image does not establish a genuine listing, ownership, availability or the identity of your contact.','图片有匹配或没有匹配，均不证明房源真实、产权、可租状态或联系人身份。')}</p>${r.attribution?`<small>${esc(r.attribution)}</small>`:''}</div>`;}
const roleNames={tenant:['Tenant','租客'],landlord:['Landlord','房东'],staff:['Reviewer','复核人员']};
const decisionNames={confirm:['Confirmed','已确认'],dispute:['Disputed','提出异议'],refuse:['Refused','拒绝参与']};
const caseStates={open:['Open','待处理'],resolved:['Resolved','已结案']};
const checkKinds={image:['Image lookup','图片反查'],cea_self_report:['CEA observation','CEA查询观察'],paynow_helper:['PayNow comparison','PayNow辅助比较']};
const enumText=(map,key)=>map[key]?tr(...map[key]):key;
const stageNames={lease_created:['Leases created','已创建租约'],movein_recorded:['Move-in recorded','已有入住记录'],landlord_joined:['Landlord joined','房东已加入'],movein_bilateral:['Move-in confirmed by both','入住记录双方确认'],moveout_recorded:['Move-out recorded','已有退租记录'],evidence_generated:['Evidence generated','已生成证据包'],core_records_and_export:['Records and export complete','记录及导出完成']};
function shell(content){document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('#language').textContent=tr('Language','语言');$('#refresh').textContent=tr('Refresh','刷新');$('#logout').textContent=tr('Sign out','退出');$('#logout').hidden=!user;const active={lease:'home',screening:'screenings',case:'cases',metrics:'cases',payee:'home',deposit:'home',evidence:'home',access:'home','listing-review':'screenings','listing-review-setup':'screenings','listing-reviews':'cases'}[view]||view;const destinations=[['home','Leases','租约'],...(user?.role==='tenant'?[['screenings','Check a listing','检查房源']]:[]),['library','Reference library','资料库'],['cases','Human review','人工复核'],['survey','Feedback','问卷']];const current=destinations.find(d=>d[0]===active);$('#app').innerHTML=(user?`<div class="workspace-bar"><small class="identity">${esc(user.name)} · ${esc(enumText(roleNames,user.role))}</small><button type="button" id="nav-toggle" data-act="toggle-nav" aria-expanded="false" aria-controls="primary-navigation">${tr('Menu','菜单')} · ${current?tr(current[1],current[2]):tr('Leases','租约')}</button><nav id="primary-navigation" class="tabs" aria-label="${tr('Main navigation','主导航')}">${destinations.map(d=>`<button type="button" data-act="${d[0]}" class="${d[0]===active?'active':''}"${d[0]===active?' aria-current="page"':''}>${tr(d[1],d[2])}</button>`).join('')}</nav></div>`:'')+content+`<footer>${tr('Device receipt does not establish ownership or independently verified capture time.','本机记录不证明产权，也不独立核实拍摄时间。')}<br>${tr('Stored on this phone. Android cloud backup is disabled.','数据存于此手机，已禁用安卓云备份。')}</footer>`;window.AndroidUI?.apply();for(const element of document.querySelectorAll('#app form,#app [data-act]'))renderedContexts.set(element,{owner:user?.id,lease,revision:viewRevision});}
function toggleNavigation(force){const button=$('#nav-toggle');if(!button)return;const open=force??button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));$('#primary-navigation').classList.toggle('is-open',open);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#nav-toggle')?.getAttribute('aria-expanded')==='true'){toggleNavigation(false);$('#nav-toggle').focus();}});
function renderAuth(){beginView('auth');shell(`<section class="auth"><h1>${tr('Your lease, recorded clearly.','清楚记录每一份租约。')}</h1><p class="muted">${tr('Keep your rental records together on this phone.','在手机上整理和保存你的租住记录。')}</p><form id="login" class="panel" novalidate><h2>${tr('Sign in','登录')}</h2>${field('email','Email','邮箱','email','','autocomplete="username" required')}${field('password','Password','密码','password','','autocomplete="current-password" required')}<label class="checklabel"><input name="remember" type="checkbox" checked>${tr('Keep me signed in on this phone','在此手机上保持登录')}</label><div class="actions"><button class="primary">${tr('Sign in','登录')}</button><button type="button" id="guest-login">${tr('Continue as guest','访客登录')}</button></div><p class="muted">${tr('Guest records stay on this phone. No password is required.','访客记录保存在此手机，无需密码。')}</p></form></section>`);}

async function home(){const ticket=beginView('home');lease=null;screening=null;const [list,drafts]=await Promise.all([pageRead('/leases',ticket),user.role==='tenant'?pageRead('/screenings',ticket):Promise.resolve([])]);if(!currentView(ticket))return;shell(`<h1>${tr('Leases','租约')}</h1><section class="panel">${list.length?list.map(l=>`<div class="listrow row lease-row"><div><h3>${esc(l.address)}</h3><small>${esc(l.start_date)} — ${esc(l.end_date)} · ${tr('Deposit','押金')} ${dollars(l.deposit_cents)}</small></div>${btn('open-lease','Open lease','打开租约',`data-id="${l.id}"`)}</div>`).join(''):`<p>${tr('No leases yet. Create a lease or accept your invitation.','暂无租约。请创建租约或接受邀请。')}</p>`}</section><div class="grid">${user.role==='tenant'?`${list.length?`<details class="create-wrap"><summary>${tr('Create another lease','创建另一份租约')}</summary>`:''}<form id="create-lease" class="panel"><h2>${tr('Create a lease','创建租约')}</h2>${field('address','Address / room','地址 / 房间','text','','required maxlength="500"')}${field('start_date','Lease start','起租日','date','','required')}${field('end_date','Lease end','退租日','date','','required')}${field('deposit','Deposit (SGD)','押金（新元）','number','','required min="0" step="0.01"')}${field('refund_date','Contract refund date','合同约定退款日','date','','required')}<label>${tr('Optional listing screening','可选：已有房源预查')}<select name="screening_id"><option value="">${tr('Do not attach a screening','不关联预查')}</option>${drafts.filter(d=>!d.lease_id).map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select></label><label class="checklabel"><input type="checkbox" name="share_screening">${tr('If selected above, copy all its observations into this lease for its members, including the invited landlord, to read.','如上方选择预查，同意将其中全部观察复制到本租约，供成员（包括受邀房东）查看。')}</label><button class="primary">${tr('Create lease','创建租约')}</button></form>${list.length?'</details>':''}`:''}${user.role==='landlord'?`<form id="accept" class="panel"><h2>${tr('Accept an invitation','接受邀请')}</h2><p>${tr('You must sign in using the identity specified by the tenant.','请使用租客指定的账户身份登录。')}</p>${field('token','Invitation credential','邀请凭证','password','','required')}<button>${tr('Accept','接受')}</button></form>`:''}</div>`);}
function latest(kind){return lease.records.find(r=>r.kind===kind)?.versions[0]||null;}
function recordServerNow(){return lease?.server_now+(performance.now()-leaseReceivedAt);}
function moveInPhotos(source=lease){const photos=new Map();for(const version of source?.records.find(r=>r.kind==='movein')?.versions||[])for(const photo of version.body.photos)if(!photos.has(photo.id))photos.set(photo.id,{...photo,reference_version:version.id,reference_seq:version.seq});return [...photos.values()];}
function configurePairing(kind){const source=lease,select=$('#camera-pair'),container=$('#camera-pairing');container.hidden=kind!=='moveout';const choices=moveInPhotos(source).filter(p=>source.photos.some(x=>x.id===p.id&&x.purged===null&&x.bytes_length>0));select.innerHTML=`<option value="">${tr('No reference selected','不关联对照照片')}</option>`+choices.map(p=>`<option value="${esc(p.id)}">${esc(p.room)} · ${date(p.received)} · ${esc(p.id.slice(0,8))}</option>`).join('');$('#camera-pair-label').firstChild.textContent=tr('Optional move-in reference','可选：入住对照照片');$('#camera-pair-preview').replaceChildren();select.onchange=()=>{const photo=choices.find(p=>p.id===select.value);$('#camera-pair-preview').innerHTML=photo?photoView(photo,false,false):`<p class="muted">${tr('This photo will remain unpaired.','此照片不关联入住对照。')}</p>`;};if(kind==='moveout'&&!choices.length)$('#camera-pair-preview').textContent=tr('No retained move-in originals are available. You can still save an unpaired move-out photo.','暂无可用的入住原片，仍可保存不关联对照的退租照片。');}
function photoView(p,editable=false,withPair=true){const purged=lease?.photos.find(x=>x.id===p.id)?.purged;const original=`<div class="photoitem">${purged?`<p class="notice">${tr('Original removed under retention policy; hash and version retained.','原片已按保留规则清理；哈希与版本仍保留。')}<br>${date(purged)}</p>`:`<img class="photo" src="/api/photos/${esc(p.id)}" alt="${esc(p.room||tr('Original photo','原片'))}" loading="lazy">`} <p><strong>${esc(p.room||'')}</strong></p><p>${esc(p.note||'')}</p><p class="meta">${p.reference_version?`${tr('Current reference annotation','当前对照批注')} · v${p.reference_seq}<br>${esc(p.reference_version)}<br>`:''}${esc(p.id)}<br>SHA-256 ${esc(p.sha256)}<br>${tr('Local backend receipt','本机处理收件')}: ${date(p.received)}<br>${tr('Device-claimed capture','设备声明拍摄')}: ${esc(p.capture_claim||'—')}${p.paired_with?'<br>'+tr('Paired with','对照照片')+': '+esc(p.paired_with):''}</p>${editable?`<label>${tr('Photo note','照片备注')}<textarea data-photo-note="${p.id}" maxlength="2000">${esc(p.note||'')}</textarea></label>`:''}</div>`;if(!p.paired_with||!withPair)return original;const reference=moveInPhotos().find(x=>x.id===p.paired_with);return `<section class="photo-comparison" data-paired-with="${esc(p.paired_with)}"><h3>${tr('Move-in / move-out comparison','入住 / 退租对照')}</h3><div class="comparison-columns"><div><h4>${tr('Move-in reference','入住对照照片')}</h4>${reference?photoView(reference,false,false):`<p>${tr('Reference unavailable; its recorded ID is retained below.','对照资料不可用，下方保留原关联ID。')}</p>`}</div><div><h4>${tr('Move-out original','退租原片')}</h4>${original}</div></div><p class="muted">${tr('Review angles, lighting and the recorded notes yourself. This view does not automatically determine damage or liability.','请自行核对角度、光线与记录备注。此对照不会自动认定损坏或责任。')}</p></section>`;}
function inventoryList(v){const photos=v.body.photos||[],missing=photos.filter(p=>!String(p.note||'').trim()).length,decided=v.decisions.filter(d=>d.kind==='confirm').map(d=>esc(d.name)).join(' · ');return `<section class="inventory" aria-label="${tr('Agreed inventory','共同确认的清单')}"><h3>${tr('Agreed inventory','共同确认的清单')} · v${v.seq}</h3><p class="muted">${tr('Each photo carries a one-line condition note. Confirming this version confirms every line below, not just the photos.','每张照片附一句状况描述。确认此版本即确认下列每一条描述，而不只是照片。')}</p>${photos.length?`<ol>${photos.map(p=>`<li><span class="meta">${esc(p.room||'')}</span><br>${String(p.note||'').trim()?esc(p.note):`<strong class="inv-missing">${tr('Condition line missing','缺少状况描述')}</strong>`}</li>`).join('')}</ol>`:`<p class="muted">${tr('No photos in this version yet.','此版本尚无照片。')}</p>`}${missing?`<p class="notice">${tr(`${missing} photo(s) have no condition line. Add one as a new version before asking for confirmation.`,`${missing}张照片缺少状况描述。请先以新版本补充，再请求确认。`)}</p>`:''}<p class="meta">${tr('Confirmed by','已确认')}: ${decided||tr('nobody yet','尚无')}<br>${tr('Photos and videos are not the same thing as an agreed inventory (JHK v JHL [2026] SGSCT 16 [63]).','法庭指出照片和视频不等同于共同确认的清单（JHK v JHL [2026] SGSCT 16 [63]）。')}</p></section>`;}
function recordPanel(kind){const v=latest(kind),tenant=user.role==='tenant',needs=v&&(v.locked||v.deadline<=recordServerNow()||['refused','disputed'].includes(v.status));const historical=lease.records.find(r=>r.kind===kind)?.versions.slice(1)||[];return `<section class="panel record-panel"><h2>${kind==='movein'?tr('Move-in record','入住记录'):tr('Move-out record','退租记录')}</h2>${v?`<div class="version">${badge(v)}<p class="meta">v${v.seq} · ${v.id}<br>SHA-256 ${v.digest}</p><p class="window">${tr('Local backend 48-hour window starts when this record is created.','48小时从本机后端创建记录时起算。')}<br>${date(v.opened)} → ${date(v.deadline)} (SGT)</p><p>${esc(v.body.note)}</p>${v.decisions.map(d=>`<p>${esc(d.name)} (${esc(d.role)}): ${esc(enumText(decisionNames,d.kind))} · ${date(d.created)}<br>${esc(d.note)}</p>`).join('')||`<p class="muted">${tr('Neither participant has decided on this version.','双方均未对该版本作出决定。')}</p>`}</div>${kind==='movein'?inventoryList(v):''}<div class="photogrid">${v.body.photos.map(p=>photoView(p,false)).join('')}</div>${!v.decisions.some(d=>d.user_id===user.id)?`<form id="decision-${kind}">${field('note','Comment / reason for dispute or refusal','批注 / 异议或拒绝原因')}<div class="actions"><button name="decision" value="confirm" ${v.deadline<=recordServerNow()?'disabled':''}>${kind==='movein'?tr('I confirm this exact version and its inventory','我确认此具体版本及其清单'):tr('I confirm this exact version','我确认此具体版本')}</button><button name="decision" value="dispute">${tr('Dispute','提出异议')}</button><button name="decision" value="refuse">${tr('Decline participation','拒绝参与')}</button></div></form>`:''}`:`<p class="muted">${tr('No record yet. The local clock starts when the first version is saved.','尚无记录。保存首个版本时服务端开始计时。')}</p>`}${tenant?`<details id="edit-${kind}"><summary>${v?tr('Add or amend as a new version','新增或修改为新版本'):tr('Start recording','开始记录')}</summary><p>${tr('Every save creates a version with no inherited confirmations. Originals cannot be overwritten.','每次保存都会创建新版本，不继承旧确认。原片不能覆盖。')}</p>${needs?`<label class="checklabel"><input type="checkbox" id="supplement-${kind}">${tr('Create a separate supplement with a new 48-hour window. Keep the old baseline.','创建独立补充版本，重新开启48小时窗口，并保留旧基线。')}</label>`:''}<form id="editrecord-${kind}">${note('note','Record note','记录备注',v?.body.note||'')}<div class="photogrid">${(v?.body.photos||[]).map(p=>`<label>${esc(p.room)}${kind==='movein'?` · ${tr('condition line','状况描述')}`:''}<textarea data-photo-note="${p.id}" maxlength="2000" ${kind==='movein'?`placeholder="${tr('e.g. Scratch, left wall, about 10 cm','例如：左墙划痕，约10厘米')}"`:''}>${esc(p.note)}</textarea></label>`).join('')}</div><button>${tr('Save new version','保存新版本')}</button></form><div class="actions">${btn('camera','Take an original photo','拍摄原片',`data-kind="${kind}"`)}</div>${lease.photos.filter(p=>!p.purged&&!lease.records.some(r=>r.versions.some(z=>z.body.photos.some(x=>x.id===p.id)))).map(p=>`<div class="listrow"><p class="meta">${tr('Uploaded original awaiting attachment','已上传、尚未关联的原片')}: ${p.id}</p>${btn('attach','Attach to this record','关联至此记录',`data-kind="${kind}" data-id="${p.id}"`)}</div>`).join('')}</details>`:''}${historical.length?`<details><summary>${tr('Earlier versions','历史版本')} (${historical.length})</summary>${historical.map(x=>`<section class="version"><h3>v${x.seq}</h3>${badge(x)}<p class="meta">${x.id}<br>${x.digest}</p><p>${esc(x.body.note)}</p>${x.decisions.map(d=>`<p>${esc(d.name)}: ${esc(enumText(decisionNames,d.kind))} · ${esc(d.note)}</p>`).join('')}<div class="photogrid">${x.body.photos.map(p=>photoView(p)).join('')}</div></section>`).join('')}</details>`:''}</section>`;}
async function openLease(id){const ticket=beginView('lease'),data=await pageRead('/leases/'+id,ticket);if(!currentView(ticket))return;const checks=await pageRead('/leases/'+id+'/checks',ticket);if(!currentView(ticket))return;lease=data;leaseReceivedAt=performance.now();shell(`<h1>${esc(lease.address)}</h1><p class="meta lease-dates">${esc(lease.start_date)} → ${esc(lease.end_date)}<span class="lease-id">${lease.id}</span></p>${leaseProgress()}<div class="notice">${tr('Single-party records remain single-party until both members explicitly confirm the same version. No response or expiry never means agreement.','单方记录只有在双方明确确认同一版本后才变成双方确认。未回应或超时不代表认可。')}</div><div class="split"><div>${recordPanel('movein')}<section class="panel members-panel" id="lease-members"><h2>${tr('Lease members','租约成员')}</h2>${lease.members.map(m=>`<p>${esc(m.name)} · ${esc(enumText(roleNames,m.role))}</p>`).join('')}${user.role==='tenant'&&!lease.members.some(m=>m.role==='landlord')?`<form id="invite">${field('email','Landlord account email','房东账户邮箱','email','','required')}<button>${tr('Create 48h invitation','创建48小时邀请')}</button></form>`:''}<div id="invitation-output"></div>${user.role==='tenant'?lease.invites.filter(i=>!i.accepted_by&&!i.revoked).map(i=>`<p class="meta">${esc(i.email)} · ${date(i.expires)} ${btn('revoke','Revoke','撤销',`data-id="${i.id}"`)}</p>`).join(''):''}</section>${recordPanel('moveout')}</div><aside><section class="panel deposit-panel"><h2>${tr('Deposit outstanding','待退押金')}</h2><p class="money">${dollars(lease.outstanding_cents)}</p><p>${tr('Total','总额')} ${dollars(lease.deposit_cents)} · ${tr('Returned','已退')} ${dollars(lease.returned_cents)}</p><p>${tr('Contract refund date','合同退款日')}: ${esc(lease.refund_date)}</p>${lease.refunds.map(r=>`<p>${esc(r.received_date)} · ${dollars(r.amount_cents)}<br>${esc(r.note)}</p>`).join('')}${user.role==='tenant'?`<details><summary>${tr('Record a refund','登记已收到的退款')}</summary><form id="refund">${field('amount','Amount received (SGD)','收到金额（新元）','number','','required min="0.01" step="0.01"')}${field('received_date','Date received','收到日期','date','','required')}${field('note','Note','备注')}<button>${tr('Save refund','保存退款')}</button></form></details>`:''}</section><section class="panel export-panel"><h2>${tr('Evidence export','证据导出')}</h2><p>${tr('All versions, photos, hashes and both participants’ decisions. Keep downloaded copies private.','包含所有版本、照片、哈希和双方决定。请妥善保管下载副本。')}</p><div class="actions"><a class="button" href="/api/leases/${lease.id}/export.pdf">PDF</a><a class="button" href="/api/leases/${lease.id}/export.zip">${tr('PDF + originals ZIP','PDF + 原片 ZIP')}</a></div><a href="https://www.judiciary.gov.sg/civil/cases-eligible-small-claim" target="_blank" rel="noopener noreferrer">${tr('Read SCT eligibility conditions','查看小额索偿受理条件')}</a><p class="muted">${tr('Dates alone do not establish eligibility.','日期计算不等于取得受理资格。')}</p></section><section class="panel review-panel"><h2>${tr('Request human review','申请人工复核')}</h2><form id="request-review">${note('subject','Question / correction request','问题 / 纠错申请')}<p class="muted">${tr('Only photos explicitly selected below are shared with the assigned reviewer. Open review requests hold lease photos from expiry deletion.','仅向分配的复核人员开放下方选定照片。未结复核会保留租约照片。')}</p>${lease.photos.map(p=>`<label class="checklabel"><input type="checkbox" name="photo_ids" value="${p.id}">${esc(p.id)}</label>`).join('')}<button>${tr('Submit to queue','提交至队列')}</button></form></section></aside></div>${checkPanel(checks)}`);}
function checkPanel(checks,scope='lease',target=lease?.id){return `<section class="panel listing-checks"><h2>${tr('Listing checks','房源检查')}</h2><div class="grid"><form id="image-check" data-check-scope="${scope}" data-check-target="${esc(target)}"><h3>${tr('Reverse image lookup','图片反查')}</h3>${field('url','Public listing image HTTPS URL','公开房源图片HTTPS链接','url','','required')}<label class="checklabel"><input type="checkbox" name="consent" required>${tr('Send this public image URL to the configured reverse-image service. Do not submit private move-in photos.','将此公开图片链接发送给已配置的图片反查服务。不要提交私有入住照片。')}</label><button>${tr('Run image query','执行图片查询')}</button></form><form id="cea-check" data-check-scope="${scope}" data-check-target="${esc(target)}"><h3>CEA</h3><a href="https://eservices.cea.gov.sg/aceas/public-register/sales/1/" target="_blank" rel="noopener noreferrer">${tr('Open official register','打开官方登记查询')}</a>${field('registration','Registration number checked','已查询登记号码')}${note('note','Your observed result (self-reported)','你看到的结果（用户自报）')}<button>${tr('Save my observation','保存我的观察')}</button></form></div><details><summary>${tr('PayNow visible-name helper','PayNow可见姓名辅助比较')}</summary><form id="paynow" data-check-scope="${scope}" data-check-target="${esc(target)}">${field('visible','Visible recipient name','可见收款人姓名')}${field('expected','Expected name','预期姓名')}<p class="muted">${scope==='screening'?tr('Saves both names privately to this screening. They are shared only if you later attach it to a lease with consent. Enter visible text, not account numbers.','两项姓名先保存到此私有预查；仅在之后同意关联租约时共享。请只输入可见文字，不要输入账号。'):tr('Saves both entered names to this private lease for its members. Enter visible text only, not account numbers.','两项姓名将保存到此私有租约，供成员查看。仅输入可见文字，不要输入账号。')}</p><button>${tr('Compare and save observation','比较并保存观察')}</button></form></details><p class="notice">${tr('Image similarity, register entries and name matches do not establish a genuine listing, ownership or the identity of your contact.','相似图片、登记条目与姓名匹配均不证明房源真实、产权或联系人的身份。')}</p>${checks.map(renderCheck).join('')||`<p>${scope==='screening'?tr('No observations saved for this screening yet.','此预查尚未保存观察。'):tr('No checks have been performed for this lease.','尚未对此租约执行检查。')}</p>`}</section>`;}
async function screenings(){const ticket=beginView('screenings');screening=null;const rows=await pageRead('/screenings',ticket);if(!currentView(ticket))return;shell(`<h1>${tr('Check a listing before creating a lease','创建租约前检查房源')}</h1><p class="notice">${tr('Private to your account until you explicitly attach a snapshot to a new lease. No lease is created here.','在你明确关联到新租约前，仅本人可见。这里不会创建租约。')}</p><form id="create-screening" class="panel">${field('title','Listing label / address for your reference','房源标签 / 供本人参考的地址','text','','required maxlength="500"')}<button>${tr('Start private screening','开始私有预查')}</button></form><section class="panel">${rows.map(d=>`<div class="listrow"><h2>${esc(d.title)}</h2><p>${d.lease_id?tr('Linked snapshot · read only','已关联快照 · 只读'):tr('Private draft','私有草稿')} · ${date(d.created)}</p>${btn('open-screening','Open screening','打开预查',`data-id="${esc(d.id)}"`)}</div>`).join('')||tr('No screenings yet.','暂无预查。')}</section>`);}
async function openScreening(id){const ticket=beginView('screening'),d=await pageRead('/screenings/'+id,ticket);if(!currentView(ticket))return;screening=d;shell(`<h1>${esc(d.title)}</h1><p class="meta">${esc(d.id)} · ${date(d.created)}</p><p class="notice">${tr('Private workspace. These observations do not certify a listing, identity or ownership. Choose this screening and explicitly allow sharing when creating a lease.','私有工作区。观察结果不认证房源、身份或产权。创建租约时需选择此预查并明确同意共享。')}</p>${d.lease_id?`<section class="panel"><p>${tr('Linked snapshot is locked. Continue with new checks in the lease.','已关联快照已锁定，请在租约中继续添加检查。')}</p>${btn('open-lease','Open linked lease','打开关联租约',`data-id="${esc(d.lease_id)}"`)}${d.checks.map(renderCheck).join('')}</section>`:checkPanel(d.checks,'screening',d.id)}${btn('home','Create a lease / return to leases','创建租约 / 返回租约')}`);}
async function submitCheck(data,form){const ticket=viewRevision,owner=user.id,type=form.dataset.checkScope,id=form.dataset.checkTarget,target={type,id,path:(type==='screening'?'/screenings/':'/leases/')+id+'/checks'};await api(target.path,data);if(user?.id!==owner)return;if(currentView(ticket)&&view===target.type&&(target.type==='screening'?screening?.id:lease?.id)===target.id){if(target.type==='screening')await openScreening(target.id);else await openLease(target.id);}else notify(tr('Observation saved to its original workspace.','观察已保存到原工作区。'));}
async function library(){const ticket=beginView('library'),c=await pageRead('/reference',ticket);if(!currentView(ticket))return;referenceCatalog=c;shell(`<h1>${tr('Reference library','资料库')}</h1><p>${tr('Snapshot accessed','资料访问日期')} ${esc(c.accessed)}</p><div class="notice">${tr('Historical whole-flat approvals are not currently available properties or room rents. Source offers are not reconfirmed.','历史整租批准记录不是当前可租房源或房间租金。公开房源线索未经重新确认。')}</div><section class="panel"><p>${Object.entries(c.counts).map(([k,v])=>esc(enumText({...referenceKinds,sources:['Sources','来源']},k))+': '+v.toLocaleString()).join(' · ')}</p><form id="reference-search"><label>${tr('Dataset','数据集')}<select name="kind"><option value="listings">${tr('Listing leads','房源线索')}</option><option value="agents">CEA</option><option value="rentals">${tr('Historical whole-flat rents','历史整租租金')}</option><option value="guides">${tr('Guides','指南')}</option><option value="community">${tr('Community','社区')}</option></select></label>${field('q','Search terms (all words must match)','搜索词（每个词均需匹配）','search','','maxlength="100"')}<p class="muted">${tr('Try Jurong, Bedok or 2026-09. The property and agent snapshots use English; guides and community summaries support Chinese. Empty search shows all records in this dataset.','可尝试 Jurong、Bedok 或 2026-09。房源及中介快照以英文记录；指南与社区摘要可搜中文。留空则显示该数据集全部记录。')}</p><button>${tr('Search','搜索')}</button></form><div id="reference-results" aria-live="polite" tabindex="-1"></div></section><details class="panel"><summary>${tr('Source coverage and limitations','来源覆盖与限制')}</summary>${c.coverage.map(x=>`<div class="listrow"><h3>${esc(x.platform)}</h3><p>${esc(x.status)} · ${esc(x.detail)}</p></div>`).join('')}${c.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.publisher)}</a> · ${esc(s.accessed)}</p>`).join('')}</details>`);}
function referenceRow(kind,row){
 const source=referenceCatalog?.sources.find(s=>s.id===row.source_id),url=row.url||source?.url;
 let title,body;
 if(kind==='listings'){title=row.title;body=`${esc(row.area)} · ${esc(row.type)} · ${dollars(row.rent*100)}<p>${tr('Source offer, availability and ownership not reconfirmed.','来源房源线索，可租状态及产权未经重新核实。')}</p>`;}
 else if(kind==='agents'){title=row.name;body=`${esc(row.reg)} · ${esc(row.agency)}<p>${tr('Agency licence','公司牌照')}: ${esc(row.licence)}<br>${esc(row.start_date)} → ${esc(row.end_date)}</p><p>${tr('Registry snapshot only; this does not identify the person contacting you.','仅为登记快照，不核实联系人的身份。')}</p>`;}
 else if(kind==='rentals'){title=[row.town,row.block,row.street].join(' ');body=`${esc(row.month)} · ${esc(row.type)} · ${dollars(row.rent*100)}<p>${tr('Historical whole-flat approval, not a currently available room.','历史整租批准记录，不是当前可租房间。')}</p>`;}
 else {title=row['title_'+lang];body=`<p>${esc(row['body_'+lang])}</p>`;}
 return `<article class="listrow"><h3>${esc(title)}</h3>${body}<p class="meta">${esc(source?.publisher||row.publisher||row.platform||'')} ${(row.accessed||source?.accessed)?' · '+esc(row.accessed||source.accessed):''}</p>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${tr('Open source','查看来源')}</a>`:''}</article>`;
}
async function searchReference(kind,q,offset=0){
 const target=$('#reference-results'),ticket=viewRevision,request=++referenceRequest,owner=user?.id;
 if(!target)return;
 target.setAttribute('aria-busy','true');target.textContent=tr('Searching…','正在搜索…');
 const current=()=>currentView(ticket)&&request===referenceRequest&&target.isConnected&&user?.id===owner;
 try{
  const data=await api('/reference?'+new URLSearchParams({kind,q,offset}));if(!current())return;
  referenceResults.set(target,{kind:data.kind,query:data.query});
  const range=data.rows.length?`${data.offset+1}–${data.offset+data.rows.length}`:'0';
  target.innerHTML=`<h2>${esc(enumText(referenceKinds,data.kind))}</h2><p class="reference-query">${tr('Searched','已搜索')}: ${data.query?esc(data.query):tr('All records','全部记录')} · ${range} / ${data.total.toLocaleString()}</p>${data.rows.map(row=>referenceRow(data.kind,row)).join('')||`<p>${tr('No matching records in this snapshot. This is not evidence of fraud, absence from the live register, or no properties being available.','此快照内没有匹配记录。这不证明存在诈骗、未列入实时登记或没有可租房源。')}</p>`}<div class="actions">${data.offset?btn('reference-page','Previous page','上一页',`data-offset="${Math.max(0,data.offset-data.limit)}"`):''}${data.has_more?btn('reference-page','Next page','下一页',`data-offset="${data.offset+data.limit}"`):''}</div>`;
  target.focus();
 }catch(e){if(!current())return;target.textContent=tr('Search did not complete. Check the error and retry.','搜索未完成，请检查错误后重试。');throw e;}
 finally{if(current())target.removeAttribute('aria-busy');}
}

