async function openCase(id){const ticket=beginView('case'),c=await pageRead('/cases/'+id,ticket);if(!currentView(ticket))return;shell(`<h1>${tr('Review request','复核申请')}</h1><section class="panel"><p class="meta">${c.id}</p><h2>${esc(c.subject)}</h2><p>${esc(enumText(caseStates,c.status))} · ${tr('Retention hold','到期清理保留')}: ${c.hold?'Yes / 是':'No / 否'}</p><div class="photogrid">${c.photo_ids.map(p=>`<img class="photo" src="/api/cases/${c.id}/photos/${p}" alt="${esc(p)}">`).join('')}</div>${c.replies.map(r=>`<div class="listrow"><small>${esc(r.author)} · ${date(r.created)}</small><p class="pre">${esc(r.body)}</p></div>`).join('')}<form id="case-reply" data-id="${id}">${note('body','Response / correction (appends to history)','答复 / 纠正（追加保存历史）')}<button>${tr('Send response','提交答复')}</button></form>${user.role==='staff'&&c.status!=='resolved'?btn('resolve-case','Resolve and release retention hold','结案并解除清理保留',`data-id="${id}"`):''}</section>`);}
const questions={pu:[['Helps me document housing condition','帮助我记录房屋状况'],['Helps me review the same evidence with my landlord','帮助我与房东审阅同一份证据'],['Helps me keep track of my deposit','帮助我追踪押金'],['Would be useful in my renting process','对我的租房过程有用']],peou:[['Learning to use it is easy','容易学习如何使用'],['The next action is clear','下一步操作清楚'],['Recording photos and notes is easy','容易记录照片和备注'],['I can use it without assistance','无需协助即可使用']]};
