function editData(kind,additional){const form=$('#editrecord-'+kind),source=renderedContexts.get(form)?.lease||lease,v=source.records.find(r=>r.kind===kind)?.versions[0]||null;const photos=(v?.body.photos||[]).map(p=>({...p,note:form?.querySelector(`[data-photo-note="${p.id}"]`)?.value??p.note}));if(additional)photos.push(additional);return {expected_version:v?.id??null,note:form?.elements.note.value||v?.body.note||'',photos,supplement:Boolean($('#supplement-'+kind)?.checked)};}
