$('#language').onclick=async()=>{const button=$('#language');if(button.disabled)return;button.disabled=true;const saved=captureLanguageDraft();try{lang=lang==='en'?'zh':'en';localStorage.setItem('safelease-language',lang);Native.setting('language',lang);$('#message').style.display='none';if(view==='getting-started')await GettingStarted.open();else if(view==='showcase')GettingStarted.showcase();else if(view==='settings')AndroidUI.settings();else if(user)await refresh();else renderAuth();restoreLanguageDraft(saved);}finally{button.disabled=false;}};
