/* 1.7.0: one next step for the lease, derived from its records. */
function leaseProgress(){
if(!lease||!user||!['tenant','landlord'].includes(user.role))return '';
const mi=latest('movein'),mo=latest('moveout'),tenant=user.role==='tenant',landlord=lease.members.some(m=>m.role==='landlord'),
mine=v=>!!v&&v.decisions.some(d=>d.user_id===user.id),open=v=>!!v&&v.status==='pending'&&v.deadline>recordServerNow(),
agreed=lease.records.find(r=>r.kind==='movein')?.versions.some(v=>v.status==='bilateral'),refunded=lease.deposit_cents>0&&lease.outstanding_cents<=0,days=window.Model?.daysLeft?Model.daysLeft(lease.end_date):999;
const steps=[[tr('Move-in recorded','已有入住记录'),!!mi],[tr('Landlord joined','房东已加入'),landlord],[tr('Both confirmed move-in','双方确认入住'),!!agreed],[tr('Move-out recorded','已有退租记录'),!!mo],[tr('Deposit returned','押金已退还'),refunded]];
let next=null;
if(tenant){
if(!mi&&days>30)next=['edit-movein',tr('Record the move-in condition','记录入住状况'),tr('Take original photos room by room with the in-app camera, then save the first version.','用应用内相机逐个房间拍摄原片，然后保存首个版本。')];
else if(!mo&&days<=30)next=['edit-moveout',tr('Record the move-out condition','记录退租状况'),tr('Before handover, photograph the same rooms and pair them with the move-in originals.','交房前拍摄相同房间，并与入住原片对照。')];
else if(!mi)next=['edit-movein',tr('Record the move-in condition','记录入住状况'),tr('Take original photos room by room with the in-app camera, then save the first version.','用应用内相机逐个房间拍摄原片，然后保存首个版本。')];
else if(!landlord)next=['lease-members',tr('Invite your landlord to confirm','邀请房东确认'),tr('Create a 48-hour invitation for the landlord account named in your agreement.','为租约上的房东账户创建48小时邀请。')];
else if(open(mi)&&!mine(mi))next=['decision-movein',tr('Confirm your own move-in version','确认你自己的入住版本'),tr('Each member decides on the same exact version. Check every condition line first.','双方须对同一具体版本分别作出决定，请先核对每一条状况描述。')];
else if(open(mi))next=['record-movein',tr('Waiting for the landlord’s decision','等待房东决定'),tr('No response never means agreement. You can keep recording meanwhile.','未回应不代表认可，期间可以继续记录。')];
else if(!agreed&&mi.status!=='bilateral'&&!mo)next=['edit-movein',tr('Add a supplement to the move-in record','为入住记录添加补充版本'),tr('The earlier version stays unchanged. A supplement opens a new 48-hour window.','原版本保持不变，补充版本会重新开启48小时窗口。')];
else if(!mo)next=['edit-moveout',tr('Record the move-out condition','记录退租状况'),tr('Before handover, photograph the same rooms and pair them with the move-in originals.','交房前拍摄相同房间，并与入住原片对照。')];
else if(open(mo)&&!mine(mo))next=['decision-moveout',tr('Confirm your own move-out version','确认你自己的退租版本'),tr('Check the photos and notes, then decide on this exact version.','核对照片与备注，再对此具体版本作出决定。')];
else if(!refunded)next=['deposit',tr('Track your deposit refund','跟踪押金退款'),tr('Record money actually received, then export your evidence.','登记实际收到的退款，然后导出证据。')];
else next=['export',tr('Keep a copy of your evidence','保存一份证据'),tr('Export every version, photo and decision, and keep the file private.','导出所有版本、照片与决定，并妥善保管。')];
}else{
const pend=[['movein',mi],['moveout',mo]].find(([,v])=>open(v)&&!mine(v));
next=pend?['decision-'+pend[0],pend[0]==='movein'?tr('Review the move-in version','审阅入住版本'):tr('Review the move-out version','审阅退租版本'),tr('Check every photo and note, then confirm, dispute or decline this exact version.','核对每张照片与备注，再对此具体版本确认、提出异议或拒绝。')]:['record-movein',tr('Nothing is waiting for your decision','暂无待你决定的事项'),tr('New versions from the tenant will appear here.','租客的新版本会显示在这里。')];
}
const done=steps.filter(x=>x[1]).length;
return `<section class="panel lease-progress" aria-label="${tr('Lease progress','租约进度')}"><div class="lp-head"><span class="lp-count">${done}/${steps.length}</span><div><small>${tr('Next step','下一步')}</small><h2>${next[1]}</h2></div></div><p>${next[2]}</p><ol class="lp-steps">${steps.map(([label,ok])=>`<li class="${ok?'done':''}">${label}</li>`).join('')}</ol>${next[0]!=='record-movein'||tenant?`<button type="button" class="primary" data-step-target="${next[0]}">${tr('Go to this step','前往此步骤')}</button>`:''}</section>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-step-target]');if(!b)return;const t=b.dataset.stepTarget,el=t==='record-movein'?document.querySelector('.record-panel'):document.getElementById(t)||document.querySelector('.'+t+'-panel');if(!el)return;if(el.tagName==='DETAILS')el.open=true;if(t==='deposit')el.querySelector('details')?.setAttribute('open','');const box=el.tagName==='FORM'?el.closest('section')||el:el;box.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>el.querySelector('input:not([type=hidden]),textarea,summary,button')?.focus({preventScroll:true}),400);});
